  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    # Validate nodes exist in core
    for n in nodes:
        if n not in core:
            raise ValueError(f"Node {n} missing from core_distance")
    # Build edges with mutual reachability
    edges = []
    for a, b, dist in case['distances']:
        if a not in core or b not in core:
            raise ValueError(f"Node {a} or {b} not in core_distance")
        # Canonicalize endpoints
        if a > b:
            a, b = b, a
        wt = max(core[a], core[b], dist)
        edges.append((wt, a, b))
    # Sort deterministically
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for wt, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, wt])
            total_weight += wt
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected; no spanning tree exists")
    return {"mst_edges": mst_edges, "total_weight": total_weight}
